#!/usr/bin/env python3
"""Informe integral: cifras del snapshot primario, escenarios explícitos y lectura política."""
import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];SITE=ROOT/'deploy/site-overlay'
D=json.loads((SITE/'assets/data/presupuesto-2027.json').read_text())
def n(x,d=1):return f'{x:,.{d}f}'.replace(',','X').replace('.',',').replace('X','.')
def m(x):return '$'+n(x/1e6)+' M'
def pct(x):return ('+' if x>0 else '')+n(x)+'%'
def real(row,f=1.2154):return (row['proyecto_2027']/row['vigente_2026_06_30']/f-1)*100
def table(rows,kind,share=False):
 head='<th scope="col">Participación 2027</th>' if share else ''
 body=''
 for i,r in enumerate(rows):
  body+=f'<tr><th scope="row">{html.escape(r["nombre"])}</th><td>{m(r["vigente_2026_06_30"])}</td><td>{m(r["proyecto_2027"])}</td><td>{pct((r["proyecto_2027"]/r["vigente_2026_06_30"]-1)*100)}</td><td data-general-real="{kind}:{i}">{pct(real(r))}</td>'+ (f'<td>{n(r["proyecto_2027"]/D["total_2027"]*100,2)}%</td>' if share else '')+'</tr>'
 return '<div class="p27-table-wrap" tabindex="0" role="region" aria-label="Comparación '+kind+'"><table><caption>Base vigente al 30/06/2026 · proyecto 2027 · millones de pesos</caption><thead><tr><th scope="col">Concepto</th><th scope="col">Vigente 2026</th><th scope="col">Proyecto 2027</th><th scope="col">Nominal</th><th scope="col" data-general-column>Real · 21,54%</th>'+head+'</tr></thead><tbody>'+body+'</tbody></table></div>'
F={r['nombre']:r for r in D['funciones']};C={r['nombre']:r for r in D['composicion_funciones']}
def sector(name,title,text,question):
 r=F[name];share=r['proyecto_2027']/D['total_2027']*100;before=r['vigente_2026_06_30']/D['vigente_2026_06_30']*100;c=C.get(name)
 detail=''
 if c:
  detail=f'<p class="p27-source">Composición 2027: personal {m(c["personal"])}; consumo {m(c["consumo"])}; transferencias corrientes {m(c["transferencias"])}; capital {m(c["capital"])}.'+(f' Otros gastos corrientes {m(c["otros"])}.' if c['otros'] else '')+' Fuente: Planilla 1.</p>'
 return f'<article class="p27-sector"><h3>{title}</h3><p><strong>{m(r["proyecto_2027"])}</strong> · {n(share,2)}% del gasto (antes {n(before,2)}%) · {pct((r["proyecto_2027"]/r["vigente_2026_06_30"]-1)*100)} nominal · <span data-sector-real="{html.escape(name)}">{pct(real(r))}</span> real en el escenario seleccionado.</p>{detail}<p>{text}</p><div class="p27-callout"><strong>La pregunta desde los barrios</strong><p>{question}</p></div></article>'
sectors=''.join([
sector('Educación','Educación: sostener una red pública con igualdad de oportunidades','Educación es la función de mayor monto. El aumento nominal de 20,9% no alcanza la inflación promedio de 21,54% del primer escenario: una caída real de 0,5%. Con 23%, la pérdida sería 1,7%. Que conserve alrededor de una quinta parte del presupuesto no demuestra por sí solo suficiencia frente a matrícula, salarios o infraestructura. Su participación baja levemente, del 19,71% al 19,65%. Las remuneraciones representan 59,1% de la función y el capital 9,9%; las transferencias requieren apertura por destinatario antes de atribuirlas íntegramente a un tipo de establecimiento.','¿Cómo se distribuyen los recursos entre gestión estatal y privada, niveles y modalidades? ¿Qué escuelas tienen problemas edilicios, qué vacantes faltan y qué metas de becas, comedores y mantenimiento sostendrá cada programa? Proponemos evaluar recursos por alumno y necesidades, sin repartir el agregado automáticamente por comuna.'),
sector('Promoción y acción social','Desarrollo social y cuidados: el agregado casi empata, las necesidades no','La función crece 21,2% nominal y pierde 0,3% real con el primer escenario. No hay una reducción nominal: sí una asignación que prácticamente no mejora su poder de compra. Las transferencias corrientes suman $1.678.592 millones, 75,1% de la función. Ese peso vuelve decisivo conocer beneficiarios, montos unitarios y actualización de prestaciones. Un agregado estable puede contener programas con aumentos y otros con retracción.','¿Qué cobertura y monto real tendrán las políticas de alimentación, niñez, discapacidad, personas mayores y situación de calle? ¿Se ajustan las prestaciones según precios relevantes para los hogares? Desde 100 Barrios proponemos proteger continuidad de cuidados y asistencia, con criterios públicos de acceso.'),
sector('Vivienda y Urbanismo','Vivienda: mirar soluciones, no sólo partidas','Vivienda y Urbanismo crece 20,4% nominal y pierde 0,9% real en el primer escenario. El 77,6% de la función corresponde a capital: su capacidad de respuesta depende especialmente de obras, etapas y desembolsos. Esta función no equivale al presupuesto del Instituto de Vivienda, ni permite deducir cuántas viviendas se entregarán. Urbanización, infraestructura y otras intervenciones deben separarse de soluciones habitacionales nuevas.','¿Cuántas viviendas, conexiones y regularizaciones se prevén, en qué barrios y con qué calendario? ¿Qué recursos atienden alquileres y riesgo de desalojo? Proponemos cruzar inversión con déficit habitacional y servicios básicos; una localización administrativa no define por sí sola al beneficiario.'),
sector('Transporte','Transporte: el anuncio del subte y el conjunto no son lo mismo','El gasto funcional aumenta apenas 5,2% nominal y pierde 13,5% real con 21,54% de inflación promedio. Su participación cae del 5,97% al 5,18%. El capital suma $1.133.778 millones, 90,8% de la función. El Mensaje destaca Línea F, modernización de la B y obras en otras líneas; un aumento en una obra concreta puede coexistir con una caída real del conjunto. No se atribuye esa caída automáticamente al servicio operativo del subte.','¿Qué obras explican la concentración de inversión? ¿Qué partidas sostienen frecuencia, accesibilidad, mantenimiento y subsidios? Queremos evaluar el costo de viajar para estudiar, trabajar y atenderse, sin confundir presupuesto de obras con tarifa o calidad del servicio.'),
sector('Seguridad interior','Seguridad: más recursos exigen control y resultados','Seguridad interior crece 22,1% nominal: +0,4% real con 21,54%, pero −0,8% con 23%. Es un ejemplo de conclusión sensible al escenario. Su participación sube de 14,24% a 14,34%. El personal concentra 61,8% de la función; el capital suma $423.099 millones. El aumento no demuestra una mejora de seguridad ni justifica restricciones de derechos. La prevención del delito debe evaluarse con información independiente sobre hechos, resultados y prácticas.','¿Qué objetivos verificables tienen los programas, cómo se controlan operativos y qué inversiones reducen riesgos reales? Desde 100 Barrios sostenemos una seguridad que proteja derechos y vida cotidiana; el gasto debe rendir cuentas a la población y al control legislativo.'),
sector('Sistema penal','Sistema penal: una expansión que requiere explicación','Es una de las funciones que más crece: 56,7% nominal y 29,0% real en el primer escenario. El capital representa 50,3% del total. La magnitud y composición obligan a examinar infraestructura, condiciones de alojamiento y políticas de reinserción. No debe sumarse nuevamente este importe al subtotal de Servicios de Seguridad, que ya lo contiene junto con Seguridad interior.','¿Cuáles son las metas de capacidad, condiciones materiales y reinserción? ¿Cómo se justifican las prioridades y su relación con prevención, educación y trabajo? El control debe incluir derechos de las personas y resultados, no sólo número de plazas.'),
sector('Trabajo','Trabajo: una caída real relevante en políticas de inserción','La función crece 6,6% nominal pero cae 12,3% real con 21,54% y 13,4% con 23%. Su participación baja de 0,93% a 0,82%. Las transferencias representan 36,9% y el consumo 40,1%. Estos agregados no permiten identificar por sí solos cuánto corresponde a capacitación, intermediación o programas de apoyo. La reducción real debe abrir una discusión sobre alcance efectivo, particularmente para jóvenes y trabajadores con inserciones precarias.','¿Cuántas personas se capacitarán, qué apoyos recibirán y cómo se medirá inserción sostenida? Proponemos vincular formación, crédito y demanda productiva territorial, con indicadores de empleo y calidad laboral.'),
sector('Cultura','Cultura: acceso y trabajo cultural bajo presión','Cultura aumenta 11,3% nominal y pierde 8,4% real en el primer escenario. El personal representa 44,6%, el consumo 40,5% y el capital 6,6%. La participación cae de 1,58% a 1,45%. Las políticas culturales no se evalúan sólo por grandes eventos: también por bibliotecas, centros, talleres y condiciones laborales. Los datos agregados no identifican qué institución absorbe cada variación.','¿Qué recursos sostienen programación y acceso gratuito en los barrios, y qué programas pierden cobertura? Proponemos comparar continuidad de actividades, participación y distribución territorial, además de ejecutar las partidas.'),
sector('Ecología','Ambiente: distinguir obras, mantenimiento y adaptación','Ecología crece 12,0% nominal pero pierde 7,9% real con el primer escenario. El capital representa 60,1%. Esa composición exige revisar proyectos y cronogramas; no convierte cada peso de la función en gasto exclusivamente climático. Proponemos vincular inversiones con riesgos de inundación, calor, déficit de verde y exposición ambiental, usando fuentes territoriales comparables.','¿Qué obras reducen riesgos y qué recursos sostienen mantenimiento, arbolado y cuidado del ambiente? ¿Se priorizan zonas con mayor exposición y menor capacidad de adaptación? La ubicación de una obra no debe confundirse con el área completa que protege.'),
sector('Servicios Urbanos','Servicios urbanos: contratos y espacio público','El aumento de 16,7% nominal se traduce en −4,0% real en el primer escenario. Consumo concentra 80,8% de la función y capital 17,5%. El peso de servicios hace indispensable abrir contratos, ajustes, plazos y prestaciones; no se puede identificar un proveedor ni afirmar sobrecostos sólo a partir de esta clasificación. La participación baja del 8,98% al 8,65%.','¿Qué servicios y niveles de cobertura compra la Ciudad, con qué mecanismo de actualización y control? Proponemos publicar indicadores de cumplimiento por zona y reclamos resueltos, junto con el costo y la ejecución.'),
sector('Agua potable y alcantarillado','Agua y saneamiento: un crecimiento que debe llegar a los hogares','La función aumenta 49,4% nominal y 22,9% real en el primer escenario. Capital concentra 90,8% del monto. El crecimiento es relevante, pero necesita verificarse por proyectos: no equivale automáticamente a más conexiones domiciliarias. Su alcance funcional puede incluir obras que deben distinguirse de las responsabilidades de los prestadores y de otras inversiones en urbanización.','¿Qué intervenciones están previstas, quién las ejecuta y qué población verá mejorar el acceso? Proponemos medir conexiones efectivas, continuidad, calidad y reducción de riesgos, sin inferir cobertura desde el monto.'),
sector('Industria y Comercio','Producción y comercio: presupuesto directo e incentivos','Industria y Comercio crece 29,4% nominal y 6,4% real con el primer escenario, pero representa apenas 0,23% del gasto. No es todo el esfuerzo económico de la Ciudad: hay promoción en otras jurisdicciones y beneficios tributarios que no figuran como gasto directo. Deben analizarse ambos instrumentos sin sumarlos como si fueran una misma partida.','¿Qué resultados de empleo, innovación y encadenamientos locales se exigen a los programas e incentivos? Proponemos orientar el apoyo a proyectos con efectos comprobables sobre producción y trabajo, con evaluación y condiciones públicas.'),
sector('Turismo','Turismo: crecimiento y distribución del beneficio','Turismo crece 46,5% nominal y 20,6% real en el primer escenario. El consumo representa 94,9% de la función; capital es marginal. Más gasto de promoción no demuestra automáticamente más visitantes ni beneficio distribuido. Su aporte debe evaluarse con actividad y empleo, sin ignorar impactos sobre vivienda, comercio y espacio público.','¿Qué metas tienen las campañas y acciones, cómo se medirá su efecto y qué zonas se benefician? Proponemos evaluar calidad del empleo y convivencia con la vida residencial, además de cifras agregadas de visitantes.')])
communes=''.join(f'<tr><th scope="row">Comuna {r["comuna"]}</th><td>{m(r["proyecto_2027"])}</td></tr>' for r in D['comunas_entidad'])
benefits=''.join(f'<tr><th scope="row">{r["nombre"]}</th><td>${n(r["millones_2027"])} M</td></tr>' for r in D['gasto_tributario_seleccionado'])
body=f'''<main class="p27"><p class="p27-crumb"><a href="/presupuesto/">Presupuesto</a> / Análisis integral 2027</p>
<header class="p27-hero"><div><span class="p27-kicker">PRESUPUESTO CABA 2027 · ANÁLISIS INTEGRAL</span><h1>Qué Ciudad financia el presupuesto 2027</h1><p>Ingresos, impuestos, deuda, servicios e inversiones: una lectura de las prioridades del proyecto desde 100 Barrios. El equilibrio de las cuentas no alcanza para evaluar si el presupuesto responde a las necesidades de quienes viven y trabajan en la Ciudad.</p><div class="p27-meta">Versión presentada el 30/09/2026 · Corte del análisis: 08/10/2026 · Proyecto, no ley sancionada</div><a class="p27-action" href="/presupuesto/ejecucion/">Consultar la ejecución presupuestaria</a></div><aside><span>LA PREGUNTA DISTRIBUTIVA</span><blockquote>¿Quién aporta, qué se prioriza y qué llega efectivamente a cada barrio?</blockquote><a href="/presupuesto/2027/salud/">Abrir el especial de Salud →</a></aside></header>
<div class="p27-stats"><div><b>$24,094 B</b><span>gasto total proyectado</span><small>Billones de pesos · corriente y capital</small></div><div><b>−0,3%</b><span>variación real del total</span><small>Escenario promedio de precios: 21,54%</small></div><div><b>−11,8%</b><span>variación real de capital</span><small>Frente al vigente al 30/06/2026</small></div><div><b>0,0055%</b><span>superávit financiero / recursos</span><small>Margen fiscal proyectado tras intereses</small></div></div>
<nav class="p27-index" aria-label="Capítulos del presupuesto 2027"><a href="#lectura">Lectura general</a><a href="#metodo">Comparar bien</a><a href="#ingresos">Ingresos</a><a href="#impuestos">Impuestos</a><a href="#estructura">Gasto y personal</a><a href="#deuda">Deuda y riesgos</a><a href="#funciones">Funciones</a><a href="#salud">Salud</a><a href="#sectores">Políticas sectoriales</a><a href="#inversion">Inversión</a><a href="#comunas">Comunas</a><a href="#control">Control y propuestas</a><a href="#fuentes">Fuentes</a></nav>
<section id="lectura"><span class="p27-kicker">01 · UNA LECTURA DE CONJUNTO</span><h2>El equilibrio fiscal no responde toda la pregunta</h2><p>El proyecto prevé recursos por $24,096 billones y gastos por $24,094 billones. El gasto aumenta 21,2% nominal frente al vigente al 30 de junio de 2026. Con inflación promedio estimada de 21,54%, el crecimiento no preserva completamente su poder de compra: −0,3%; con 23%, −1,5%. No es una contracción nominal, ni un resultado observado: es una comparación entre créditos y escenarios de precios.</p><p>Dentro de ese conjunto, las prioridades cambian. Salud pierde participación; Transporte, Trabajo, Cultura y Ecología registran caídas reales más marcadas. Seguridad interior queda muy cerca del empate en el primer escenario; Sistema penal crece significativamente. Educación conserva el mayor monto, pero tampoco alcanza la inflación promedio del primer escenario. El gasto de capital crece menos que el presupuesto y baja su participación del 20,29% al 17,95%.</p><div class="p27-callout"><strong>La posición de 100 Barrios</strong><p>El presupuesto debe proteger derechos, reducir desigualdades y ampliar la capacidad pública de resolver necesidades. La sostenibilidad fiscal es una condición de gestión, no un sustituto de esos objetivos. Proponemos discutir prioridades con metas de atención, educación, vivienda, cuidados, movilidad y trabajo; evaluar quiénes aportan y quiénes reciben; y exigir que los compromisos se traduzcan en resultados verificables.</p></div><p>Este análisis no presupone que cualquier aumento sea positivo ni que toda caída real implique automáticamente menos prestaciones. El efecto concreto depende de composición, precios específicos, eficiencia, demanda y ejecución. La discusión política se apoya en lo que las planillas sí muestran y señala dónde falta abrir los programas.</p></section>
<section id="metodo"><span class="p27-kicker">02 · BASES COMPARABLES</span><h2>Proyecto, presupuesto vigente y ejecución son cosas distintas</h2><p>La comparación del gasto usa el Cuadro 2.4 del Mensaje: $19,877 billones vigentes al 30/06/2026. Para ingresos se usa el Cuadro 3.1: $19,881 billones, porque el cálculo de recursos no es idéntico al crédito de gasto. El proyecto 2027 se obtiene de sus artículos y planillas anexas. No se compara una ley original de 2026 con un vigente a mitad de año sin señalar la diferencia.</p><p>El observatorio de ejecución usa una extracción de BA Data que incluye aplicaciones financieras: un universo distinto del gasto corriente y de capital. Por eso sus totales no se intercambian con los de este informe. La conciliación exacta requiere clasificaciones económicas y funcionales. La ejecución es devengado sobre vigente a igual fecha; no gasto proyectado dividido por el de otro año.</p><div class="p27-explorer"><fieldset><legend>Escenario de inflación promedio 2027/2026</legend><label><input name="general-scenario" type="radio" value="bloque" checked> 21,54% · estimación del bloque</label><label><input name="general-scenario" type="radio" value="alternativo"> 23,00% · estimación alternativa</label></fieldset><div class="p27-scenario-result" aria-live="polite"><b id="general-total-real">−0,3%</b><span>variación real del gasto total</span><small id="general-scenario-note">Las tablas y cifras sectoriales cambian con el escenario; el texto desarrolla el primero salvo indicación expresa.</small></div></div><p>El 18% anunciado por Hacienda es diciembre contra diciembre, no automáticamente inflación promedio anual. El crecimiento económico nacional de 4% y el dólar de $1.847,6 a diciembre de 2027 son hipótesis del proyecto. No garantizan recaudación ni costos efectivos. Las variaciones reales usan proyecto / (vigente × factor de precios), menos uno. Los valores comparativos de 2026 publicados con una décima de millón tienen esa precisión, aunque los de 2027 sean exactos en pesos.</p></section>
<section id="ingresos"><span class="p27-kicker">03 · CÓMO SE FINANCIA LA CIUDAD</span><h2>Dependencia de la actividad y de los acuerdos fiscales</h2><p>Los recursos corrientes suman $24,092 billones; los de capital apenas $3.176 millones, 0,013% del total. Esto no impide invertir: la inversión se sostiene principalmente con el excedente corriente y con la estructura de financiamiento. Las fuentes financieras se presentan aparte para evitar que deuda nueva se confunda con ingresos tributarios.</p>{table(D['ingresos_corrientes'],'ingresos_corrientes')}<p>Los tributos aportan 79,2% de los recursos totales. Ingresos Brutos, por sí solo, representa 55,1% del total de ingresos y 69,5% de los tributarios. Es una concentración que vincula la capacidad fiscal a actividad, facturación y cumplimiento. Las rentas de la propiedad crecen 58,7% nominal; no deben tratarse como un impuesto permanente ni proyectar su rendimiento mecánicamente.</p><p>La coparticipación federal tributaria de $2,226 billones no agota los recursos asociados a la relación con Nación. El Mensaje registra también transferencias corrientes por $3,018 billones y explica que allí computa ingresos vinculados a la medida cautelar sobre fondos coparticipables y al acuerdo de deuda acumulada. La comparación de estas transferencias con 2026 contiene componentes extraordinarios y diferencias de calendario: una menor tasa de crecimiento no demuestra por sí sola una nueva quita.</p><p>Los recursos no tributarios incluyen $339.803 millones de multas, frente a $220.847 millones vigentes en 2026: +53,9% nominal. Es una previsión de recaudación, no evidencia de más infracciones ni de una política deliberada para multar. Proponemos publicar sus supuestos y separar fiscalización orientada a prevención de objetivos financieros.</p></section>
<section id="impuestos"><span class="p27-kicker">04 · QUIÉN APORTA Y QUIÉN RECIBE BENEFICIOS</span><h2>El alivio tributario también tiene prioridades</h2>{table(D['tributos'],'tributos')}<p>La recaudación proyectada de Vehículos cae $124.009 millones nominales respecto del vigente: −20,1%. El Mensaje explica cambios de tramos y alícuotas, reducción de la antigüedad gravada de 25 a 20 años y un tope de variación nominal por vehículo de 0%. No es correcto llamar a toda esa diferencia «costo de una sola medida»: incorpora cambios de padrón, valuaciones, reglas y supuestos de cobro.</p><p>Inmuebles crece 26,9% nominal y Sellos 28,5%. Los ingresos agregados no describen la factura de cada contribuyente. Para evaluar progresividad hay que abrir valuaciones, alícuotas, exenciones y distribución por capacidad contributiva. El umbral de valuación fiscal para el adicional de 1% por cuota de ABL figura en el Anexo I, artículo 44, del proyecto impositivo: $41.140.000, no una estimación redondeada de la presentación.</p><p>La modificación 16 del artículo 1 del proyecto de Código Fiscal propone bonificar Ingresos Brutos a personas humanas prestadoras de servicios en el régimen simplificado: 100% en las primeras tres categorías y 75% en las siguientes cinco, sujeto a reglamentación. No equivale a eliminar el impuesto para todos los monotributistas. La ley arancelaria completa el paquete con unidades tarifarias y reglas de actualización: el costo efectivo de trámites requiere verificar la unidad y el rubro, no sólo la variación del presupuesto.</p><h3>Beneficios fiscales que también deben rendir cuentas</h3><p>El Mensaje estima los siguientes gastos tributarios: ingresos que el fisco dejaría de percibir por tratamientos especiales. Son conceptos seleccionados, no un inventario completo. No se suman regímenes que podrían superponerse ni se presentan sus importes como ahorro recuperable automáticamente.</p><div class="p27-table-wrap" tabindex="0" role="region" aria-label="Gastos tributarios seleccionados"><table><caption>Estimaciones del Mensaje, pp. 66–67 · millones de pesos</caption><thead><tr><th scope="col">Concepto</th><th scope="col">2027</th></tr></thead><tbody>{benefits}</tbody></table></div><p>El Distrito Tecnológico tiene una estimación de $192.515 millones y Microcentro de $101.402 millones. El debate debe exigir objetivos, beneficiarios, empleo generado y resultados. No se sostiene que sean recursos transferidos directamente a empresas ni que eliminarlos produzca esa recaudación sin cambios de conducta. Nuestra propuesta es evaluar adicionalidad y distribución del beneficio: qué inversión ocurre gracias al incentivo y qué retorna socialmente.</p></section>
<section id="estructura"><span class="p27-kicker">05 · CÓMO SE COMPONE EL GASTO</span><h2>Personal, servicios, transferencias e inversión</h2>{table(D['economica'],'economica',True)}<p>Las remuneraciones suman $9,950 billones, 41,3% del gasto; crecen 22,8% nominal y 1,0% real con el primer escenario. Esto no representa un aumento salarial individual: combina dotación, anualización, carreras, adicionales y previsión paritaria. No se divide el crédito por cargos para inferir salario de bolsillo. El Mensaje declara que contempla futuras negociaciones, pero el resultado salarial debe verificarse con acuerdos y ejecución.</p><p>Consumo y otros gastos corrientes primarios reúne $6,428 billones, 26,7% del total; las transferencias corrientes, $2,798 billones, 11,6%. Deben abrirse por bienes, servicios, destinatarios y programas. La Planilla 16 agrupa en consumo ciertos conceptos que la Planilla 1 identifica como otros gastos corrientes: no se mezclan renglones de ambos clasificadores para construir una suma alternativa.</p><p>Capital representa 17,95% del total, contra 20,29% vigente en 2026. Crece 7,3% nominal, por debajo del gasto corriente primario, que aumenta 23,2%. La contracción real de la inversión no se deduce de un anuncio: surge de comparar el mismo agregado económico. El dato obliga a examinar qué proyectos se priorizan y cuáles quedan postergados.</p></section>
<section id="deuda"><span class="p27-kicker">06 · RESULTADO FISCAL Y RIESGOS</span><h2>Un margen financiero muy estrecho</h2><p>Los recursos menos el gasto primario dejan $593.204 millones. Los intereses consumen $591.887 millones, 99,78% de ese superávit primario. Después de intereses queda un resultado financiero de $1.316 millones: 0,0055% de recursos. No significa que casi todo el presupuesto se destine a deuda: los intereses son 2,46% del gasto. La función Deuda Pública incluye además gastos asociados y suma $608.193 millones; esa función no es idéntica a intereses.</p><p>Los intereses aumentan 112,5% nominal frente a $278.545 millones vigentes de 2026. La función Deuda Pública crece 106,5%. El salto exige abrir instrumentos, moneda, tasa y calendario; no prueba un traslado causal desde Salud a deuda. La lectura distributiva compara prioridades y margen, no inventa un circuito de fondos.</p><h3>Ingresos y gasto no explican toda la caja</h3><p>El artículo 4 prevé fuentes financieras de $918.358 millones: $755.576 millones de endeudamiento e incremento de otros pasivos y $162.781 millones de disminución de inversión financiera. Las aplicaciones suman $919.674 millones: $613.916 millones de amortización y disminución de pasivos, y $305.758 millones de incremento de inversión financiera. La diferencia entre aplicaciones y fuentes coincide con el superávit financiero. Endeudamiento menos amortización de esos agregados no equivale necesariamente al cambio del stock de deuda, porque contienen otros pasivos y categorías diferentes.</p><p>El artículo 12 propone un máximo en circulación de $1,2 billones para crédito transitorio y letras; permite vencimientos que excedan el ejercicio dentro de sus condiciones. Es una autorización de manejo de caja, no $1,2 billones adicionales de gasto a sumar al artículo 1. Los artículos 11 y 20 regulan operaciones y adecuaciones por moneda extranjera: el riesgo cambiario debe examinarse con el perfil de deuda, no sólo el total.</p><h3>Qué pasa si la recaudación no alcanza</h3><p>Como ejercicio estático, una recaudación total 1% inferior a la prevista reduce recursos en $240.957 millones. Manteniendo el gasto, el superávit de $1.316 millones se convertiría en un déficit de unos $239.640 millones. No es un pronóstico: no incorpora reacción del gasto, efectos macroeconómicos ni otros ingresos. Sirve para mostrar que el equilibrio presupuestado tiene poco colchón. Proponemos explicitar qué servicios se protegen y qué mecanismo se activa ante desvíos.</p></section>
<section id="funciones"><span class="p27-kicker">07 · EL MAPA COMPLETO DE PRIORIDADES</span><h2>Veinte funciones, una misma comparación</h2>{table(D['funciones'],'funciones',True)}<p>Las funciones hoja suman el total de 2027. Los subtotales de Administración Gubernamental, Servicios Sociales y otras finalidades no se agregan nuevamente. Con el primer escenario, 12 de las 20 funciones quedan por debajo de los precios promedio estimados. La inflación sectorial puede diferir: el escenario común sirve para comparar prioridades, no para calcular automáticamente prestaciones.</p><p>En Administración Gubernamental, Dirección ejecutiva aumenta 30,4% nominal y Judicial 26,9%, por encima del promedio del primer escenario. Legislativa, Administración fiscal y Control de la gestión quedan por debajo. Estas funciones no equivalen a «gasto político» ni permiten clasificar su totalidad como prescindible. Corresponde abrir programas y costos antes de proponer reasignaciones concretas.</p></section>
<section id="salud"><span class="p27-kicker">08 · UNA PRIORIDAD DE 100 BARRIOS</span><h2>Salud pierde peso y merece un análisis específico</h2><p>Salud pasa de $3,357 a $3,966 billones: +18,2% nominal. Crece menos que el total y pierde participación del 16,89% al 16,46%. La diferencia para conservar su participación exacta anterior es de aproximadamente $102.419 millones. Es una referencia distributiva, no una partida eliminada. En términos reales, pierde 2,8% con inflación promedio de 21,54% y 3,9% con 23%.</p><p>Desde 100 Barrios proponemos recuperar prioridad para la red pública y evaluar atención efectiva: personal, medicamentos, equipamiento, prevención y continuidad de cuidados. La profundidad sanitaria está reunida en un apartado propio, con CeSAC, salud mental, dotación y 30 inversiones seleccionadas del PPI. La función Salud y el Ministerio no tienen el mismo total; el especial conserva esa distinción.</p><a class="p27-action" href="/presupuesto/2027/salud/">Leer el especial de Salud y sus datos →</a></section>
<section id="sectores"><span class="p27-kicker">09 · POLÍTICAS Y NECESIDADES</span><h2>Qué implica discutir cada asignación</h2><p>Estos capítulos vinculan las cifras con preguntas de cobertura y resultados. Las propuestas expresan una orientación de 100 Barrios; no se presentan como obligaciones ya aprobadas ni como pedidos de información enviados. Las composiciones son del proyecto 2027, sin afirmar cambios reales por componente cuando falta una base 2026 equivalente.</p>{sectors}</section>
<section id="inversion"><span class="p27-kicker">10 · OBRAS QUE SE CONVIERTAN EN SERVICIOS</span><h2>La inversión requiere calendario y capacidad de funcionamiento</h2><p>El capital de $4,326 billones incluye $4,317 billones de inversión real directa; transferencias de capital e inversión financiera completan ese universo. El PPI identifica obras y montos para 2027–2029, pero no equivale a una suma adicional ni a pagos ya realizados. La Planilla 1 distribuye capital por función; el PPI ofrece otra apertura por proyectos. Sus alcances deben conciliarse, no sumarse.</p><p>Transporte concentra $1,134 billones de capital funcional; Vivienda y Urbanismo $641.323 millones; Educación $469.974 millones; Salud $435.619 millones; Seguridad interior $423.099 millones. La lista compara capital por función, no ministerios. Permite discutir selección de proyectos junto con necesidad territorial, costos y plazos; no alcanza para afirmar sobreprecio o abandono.</p><p>El proyecto de Línea F figura en el PPI con $368.930 millones en 2027, $487.862 millones en 2028 y $435.591 millones en 2029. Son previsiones plurianuales de ese renglón específico, no costo total de la línea ni tres gastos que correspondan todos a 2027. El artículo 21 contiene las condiciones para comprometer ejercicios futuros. Antes de contratar deben examinarse garantías, hitos y capacidad financiera de los años siguientes.</p><p>Proponemos una ficha por obra: identificación, fuente de financiamiento, crédito aprobado y vigente, contratación, inicio, avance físico, devengado, pagos y fecha de puesta en servicio. En escuelas, hospitales y vivienda hay que agregar capacidad efectivamente habilitada. Una obra terminada sin personal, conexiones o insumos no equivale al resultado público esperado.</p></section>
<section id="comunas"><span class="p27-kicker">11 · DESCENTRALIZACIÓN Y TERRITORIO</span><h2>Presupuesto comunal no es todo el gasto en cada comuna</h2><p>La Planilla 34 enumera las entidades Comuna. Los ministerios ejecutan también obras y servicios en esos territorios; por eso estos montos no representan gasto total ni gasto por habitante. La localización física de un efector tampoco equivale a población exclusivamente beneficiada. El presupuesto de un hospital no se atribuye entero a la comuna donde funciona.</p><details><summary>Ver los créditos de las 15 entidades comunales</summary><table class="p27-simple"><caption>Proyecto 2027 · millones de pesos · Planilla 34</caption><thead><tr><th scope="col">Entidad</th><th scope="col">Monto</th></tr></thead><tbody>{communes}</tbody></table></details><p>Una lectura territorial completa necesita tres capas separadas: competencias y créditos comunales; localización de intervenciones ministeriales; población y necesidades atendidas. Para las comunas 4, 7 y 9 proponemos abrir recorridos de salud, vivienda, educación, cuidados y espacio público, sin extrapolar inversión por barrio a partir de una tabla administrativa.</p><p>No se afirma aquí una variación de descentralización entre 2026 y 2027: para eso hay que reconstruir entidades equivalentes, competencias y base vigente. La prioridad es evaluar si las transferencias de responsabilidades cuentan con crédito, personal y herramientas, y si su distribución atiende desigualdades.</p><div class="p27-links"><a href="/presupuesto/territorio/">Presupuesto y territorio</a><a href="/presupuesto/descentralizacion/">Descentralización</a><a download href="/assets/data/presupuesto-2027-comunas.csv">Descargar las 15 entidades</a></div></section>
<section id="control"><span class="p27-kicker">12 · DEL PROYECTO A LA RENDICIÓN DE CUENTAS</span><h2>La aprobación no termina el debate</h2><p>El artículo 23 propone límites y reglas de modificación: hasta 5% del total definido allí para distribución funcional; el inciso Personal no puede disminuirse; existen condiciones para pasar capital y aplicaciones financieras a corriente y una excepción para créditos del Tesoro. También exige notificar mensualmente las reestructuraciones a la Comisión de Presupuesto dentro de treinta días corridos. El artículo 22 permite reestructuraciones por organización y entre comunas. No son facultades ilimitadas: deben leerse juntas, sin trasladar automáticamente una excepción a cualquier cambio.</p><p>La comparación aprobado → vigente → devengado → pagado muestra decisiones diferentes. Para verificar lo que llega a la población hay que agregar metas físicas y resultados. El Mensaje registra 35,7% de devengado general y 24,5% de capital al primer semestre 2026; Transporte 12,6%, Trabajo 23,4%, Educación 40,2% y Salud 36,5%. Son señales para abrir calendarios y programas, no pruebas automáticas de incumplimiento anual o ahorro deliberado.</p><h3>Una agenda propia para discutir el presupuesto</h3><ol class="p27-agenda"><li><strong>Proteger salud, educación y cuidados.</strong> Identificar pisos y metas de atención y cobertura, y discutir las asignaciones con escenarios de precios y necesidades.</li><li><strong>Priorizar vivienda, movilidad y servicios según desigualdad.</strong> Publicar proyectos y beneficiarios con criterios territoriales verificables.</li><li><strong>Revisar beneficios tributarios con evaluación.</strong> Exigir objetivos, distribución, empleo e inversión adicionales; distinguir alivios a hogares y pequeños contribuyentes de regímenes promocionales.</li><li><strong>Explicitar riesgos y protección ante desvíos.</strong> Mostrar cómo cambian resultado fiscal, deuda y servicios ante recaudación o costos distintos.</li><li><strong>Controlar modificaciones y ejecución.</strong> Hacer trazable cada reasignación y unirla con metas físicas, contratos y puesta en servicio.</li><li><strong>Construir alternativas financiables.</strong> Toda nueva propuesta debe identificar costo, fuente y condiciones. No se suman supuestos ahorros tributarios, deuda y recortes agregados como recursos disponibles automáticamente.</li></ol><p>Esta agenda no reemplaza una propuesta de redistribución partida por partida. Para formularla hay que abrir programas y beneficiarios, verificar costos y evaluar compatibilidades jurídicas. El análisis integral aporta una base documentada y señala qué decisiones deben fundamentarse durante el trámite.</p><a class="p27-action" href="/presupuesto/ejecucion/">Conectar las prioridades con su ejecución →</a></section>
<section id="fuentes"><span class="p27-kicker">13 · TRAZABILIDAD</span><h2>Fuentes, versión y descargas</h2><p>Fuente primaria: PDLEY-2026-36, presentado el 30/09/2026, artículos 1–6 y 11–25; Mensaje IF-2026-43937265, cuadros 2.2, 2.3, 2.4, 3.1–3.6 y capítulo de gasto; anexos IF-2026-43938160, Planillas 1, 16, 34; PPI IF-2026-43938524. En el PDF aportado, Planilla 1 está en p. 170, AIF en p. 190 y Línea F en p. 269. Los números internos de los anexos y del Mensaje no coinciden con la numeración del PDF combinado.</p><p>Paquete tributario: PDLEY 33/26, Código Fiscal, artículo 1 modificación 16; PDLEY 34/26, Ley Impositiva, Anexo I artículo 44; PDLEY 35/26, Ley Arancelaria, Anexo I artículo 1. Se describe su contenido como proyecto: no se afirma vigencia ni sanción definitiva. Las fichas y el sitio del bloque son fuentes secundarias, contrastadas con originales para las cifras utilizadas.</p><ul class="p27-sources"><li><a href="https://drive.google.com/drive/folders/11YFiAEF_12Aqe93udiwkB6Pk1upSt_Yl" target="_blank" rel="noopener">Carpeta documental aportada</a> · puede requerir acceso.</li><li><a href="https://buenosaires.gob.ar/gcaba_historico/noticias/el-ministerio-de-hacienda-y-finanzas-de-la-ciudad-presento-el-proyecto-de" target="_blank" rel="noopener">Presentación de Hacienda en la Legislatura</a> · hipótesis macro y anuncios, no ejecución observada.</li><li><a href="https://www.xn--presupuestoporteo-uxb.com.ar/" target="_blank" rel="noopener">Análisis del bloque Fuerza por Buenos Aires</a> · referencia secundaria y escenario promedio de 21,54%.</li><li><a href="/cepoes/metodologia/presupuesto/">Metodología del observatorio presupuestario</a>.</li></ul><p>Los renglones de 2026 y ciertos ingresos 2027 publicados en millones se conservan con su precisión. Las participaciones usan totales del mismo universo. Las composiciones sectoriales son 2027; no se infiere su variación sin base comparable. No se identifican beneficiarios individuales ni inversión total por barrio sin datos que permitan esa atribución.</p><div class="p27-links"><a download href="/assets/data/presupuesto-2027.json">Datos y referencias</a><a download href="/assets/data/presupuesto-2027-funciones.csv">Funciones</a><a download href="/assets/data/presupuesto-2027-tributos.csv">Tributos</a><a download href="/assets/data/presupuesto-2027-economica.csv">Composición económica</a><a download href="/assets/data/presupuesto-2027-composicion-sectorial.csv">Composición sectorial</a></div></section></main>'''
title='Qué Ciudad financia el presupuesto 2027'
